export function getMap(id){return maps.find(m=>m.id===id)||maps[0];}
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export function searchPlaces(query){const q=normalize(query);if(!q)return [];return maps.slice(1).flatMap(m=>[{name:m.name,mapId:m.id,kind:'Tavola regionale'},...m.places.map(p=>({...p,mapId:m.id}))]).filter(p=>normalize(p.name).includes(q));}
export function zoomAt(view, factor, point){const scale=Math.min(5,Math.max(1,view.scale*factor)),ratio=scale/view.scale;return {x:point.x-(point.x-view.x)*ratio,y:point.y-(point.y-view.y)*ratio,scale};}
export function clampView(view,width,height){return {...view,x:Math.min(0,Math.max(width*(1-view.scale),view.x)),y:Math.min(0,Math.max(height*(1-view.scale),view.y))};}
